(function installExportFpsPatch() {
  "use strict";

  const MIN_FPS = 1;
  const MAX_FPS = 240;
  const PATCH_MARKER = "__zoidiumExportFpsPatch";

  function normalizeDecimalText(value) {
    return String(value)
      .trim()
      .replace(/[０-９]/g, (digit) =>
        String.fromCharCode(digit.charCodeAt(0) - 0xfee0),
      )
      .replace(/[．，,]/g, ".");
  }

