    const trimmed = normalizeDecimalText(value);
    if (!trimmed) return fallback;

    const fps = Number(trimmed);
    if (!Number.isFinite(fps)) return fallback;
    return Math.min(MAX_FPS, Math.max(MIN_FPS, fps));
