    const input = document.createElement("input");
    input.classList.add("pz-inputbox");
    input.type = "text";
    input.inputMode = "decimal";
    input.autocomplete = "off";
    input.setAttribute("aria-label", "Frame rate (FPS)");
    input.style.width = "90px";
